// For each Gmail message returned, dump the raw envelope + an extracted
// summary into /data/finance-events/gmail/. Downstream workflow 16
// (cross-verify) will read these and try to match against bank-confirmed
// transactions.

const fs = require('fs');
const path = require('path');

const OUT_DIR = '/data/finance-events/gmail';
fs.mkdirSync(OUT_DIR, { recursive: true });

const items = $input.all();
const results = [];

for (const item of items) {
  const m = item.json || {};
  // n8n Gmail node shape: { id, threadId, subject, from, to, snippet, body, internalDate, ... }
  const id = m.id || m.messageId || ('unknown-' + Date.now());
  const subject = m.subject || '';
  const from = (m.from && (m.from.value && m.from.value[0] && m.from.value[0].address)) || m.from || '';
  const snippet = m.snippet || '';
  const body = (m.text && m.text.toString()) || (m.html && m.html.toString().replace(/<[^>]+>/g, ' ').slice(0, 4000)) || snippet;
  const internalDate = m.internalDate ? new Date(parseInt(m.internalDate, 10)).toISOString() : new Date().toISOString();

  // Lightweight amount extraction — first $XXX.XX-looking number in subject or body.
  const amountRegex = /\$\s?([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{2})?|[0-9]+\.[0-9]{2})/;
  let amount = null;
  const amountMatch = (subject + ' ' + body).match(amountRegex);
  if (amountMatch) amount = parseFloat(amountMatch[1].replace(/,/g, ''));

  // Direction heuristic.
  let direction = null;
  if (/deposit|received|credit|refund|incoming/i.test(subject + ' ' + body)) direction = 'in';
  else if (/withdrawal|payment|charged|debit|sent|paid|autopay/i.test(subject + ' ' + body)) direction = 'out';

  const record = {
    captured_at: new Date().toISOString(),
    source: 'gmail',
    gmail_id: id,
    internal_date: internalDate,
    from,
    subject,
    snippet,
    extracted: {
      amount,
      direction
    },
    raw_body_excerpt: String(body).slice(0, 4000)
  };

  const safeTs = (record.internal_date || record.captured_at).replace(/[:.]/g, '-');
  const filename = path.join(OUT_DIR, `${safeTs}__${String(id).slice(0, 16)}.json`);
  try {
    fs.writeFileSync(filename, JSON.stringify(record, null, 2));
    results.push({ written: filename, subject, amount, direction });
  } catch (e) {
    results.push({ error: String(e), gmail_id: id });
  }
}

return results.map(r => ({ json: r }));
